crew_phone.gd.render_actions:
func render_actions() -> void:
	if thread=="Agent Reeves":
		render_reeves_actions()
		return
	var job:=role(thread)
	if not job.is_empty():
		label(host.phone_list,job.to_upper()+" · Assigned to "+assignment(thread).capitalize())
